    const auth = Buffer.from(CLIENT_ID + ':' + CLIENT_SECRET).toString('base64');
    const d = await new Promise((resolve, reject) => {
        const req = https.request({ hostname: 'accounts.spotify.com', path: '/api/token', method: 'POST', headers: { 'Authorization': 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) } }, res => { let x = ''; res.on('data', c => x += c); res.on('end', () => { try { resolve(JSON.parse(x)); } catch(e) { reject(e); } }); });
        req.on('error', reject); req.write(body); req.end();
    });
    if (!d.access_token) throw new Error('Token refresh failed: ' + JSON.stringify(d));
    tokens.access_token = d.access_token; tokens.expires_at = now + d.expires_in * 1000;
    global.set('spotifyTokens', tokens); return tokens.access_token;
};
const apiReq = (method, token, path, body) => new Promise((resolve, reject) => {
    const b = body !== undefined ? JSON.stringify(body) : '';
    const headers = { 'Authorization': 'Bearer ' + token };
    if (b) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = Buffer.byteLength(b); }
    const req = https.request({ hostname: 'api.spotify.com', path, method, headers }, res => {
        let x = ''; res.on('data', c => x += c);
        res.on('end', () => { try { resolve({ status: res.statusCode, body: x ? JSON.parse(x) : null }); } catch(e) { resolve({ status: res.statusCode, body: x || null }); } });
    });
    req.on('error', reject); if (b) req.write(b); req.end();
});
const token = await getToken();
const r = await apiReq('GET', token, '/v1/me/player');
if (r.status === 204 || !r.body) { msg.payload = { playing: false, message: 'Nothing currently playing' }; return msg; }
if (r.status >= 400) { msg.payload = { error: 'HTTP ' + r.status + ': ' + JSON.stringify(r.body) }; return msg; }
const p = r.body;
const item = p.item;
msg.payload = {
    playing: p.is_playing,
    track: item ? item.name : null,
    artist: item ? item.artists.map(a => a.name).join(', ') : null,
    album: item && item.album ? item.album.name : null,
    progress_ms: p.progress_ms,
    duration_ms: item ? item.duration_ms : null,
    device: p.device ? { name: p.device.name, id: p.device.id, type: p.device.type, volume: p.device.volume_percent } : null,
    shuffle: p.shuffle_state,
    repeat: p.repeat_state,
    uri: item ? item.uri : null
};
return msg;",
